pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    TestToken token;

    bytes4 constant MAGIC = 0x1626ba7e;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new TestToken();
    }

    // ERC-1271 wallet: this contract is the order maker, so its signature is always valid.
    function isValidSignature(bytes32, bytes memory) external view returns (bytes4) {
        return MAGIC;
    }

    function _makeOrder(uint256 strike, uint256 premium, uint256 duration, uint256 nonce)
        internal
        view
        returns (PuttyV2.Order memory order)
    {
        order.maker = address(this);
        order.isCall = false;
        order.isLong = false; // short put -> hits the mutated early-return branch
        order.baseAsset = address(token);
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = block.timestamp + 1 days;
        order.nonce = nonce;
    }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce,
        address taker
    ) public {
        duration = bound(duration, 1, 10_000 days - 1);
        vm.assume(taker != address(0) && taker != address(this));

        vm.warp(1000);

        PuttyV2.Order memory order = _makeOrder(strike, premium, duration, nonce);
        uint256[] memory noFloors = new uint256[](0);
        bytes memory sig = new bytes(65);

        vm.prank(taker);
        uint256 positionId = c.fillOrder(order, sig, noFloors);

        // General rule: fillOrder always returns the id of the position minted to the caller.
        assertTrue(c.ownerOf(positionId) == taker);
    }
}

// Minimal ERC20 stand-in: baseAsset only needs code plus succeeding transfer calls.
contract TestToken {
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }
}
